/**
 * Owner's rules applied on top of the source catalog. data/quick-order.json
 * keeps the source values (it is regenerated by extract-catalog.mjs); these
 * overrides are applied when the page loads the catalog.
 */
import type { Offer, Product, ProductGroup } from "./types";

/**
 * Groups whose products are shown as sold out ("포켓몬 스페셜", "포켓몬 벌크").
 * Matched on the product's own group, so their copies in "예약 주문 / HOT" are sold out too.
 */
export const SOLD_OUT_GROUPS = new Set(["pokemon-other", "pokemon-bulk"]);

/** An offer as the source renders it when out of stock: "품절", price kept, no quantity stepper. */
function soldOutOffer(offer: Offer): Offer {
  return { ...offer, stockState: "out", stockText: "품절", action: "unavailable", actionKind: "empty", max: 0 };
}

function applyProduct(product: Product): Product {
  if (!SOLD_OUT_GROUPS.has(product.group)) return product;
  return { ...product, stockTotal: 0, offers: product.offers.map(soldOutOffer) };
}

export function applyShopRules(groups: ProductGroup[]): ProductGroup[] {
  return groups.map((g) => ({ ...g, rows: g.rows.map(applyProduct) }));
}
